INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Onboarding new employees effectively can have a lasting impact on how quickly they become productive members of a team. A well-structured onboarding program typically includes clear information about company policies, introductions to key colleagues, and a defined set of goals for the first few months. Many organizations now extend onboarding beyond the first week, recognizing that new employees often need ongoing support as they adjust to new systems and expectations. Assigning a mentor or buddy can help new hires feel more comfortable asking questions without hesitation. Research suggests that employees who receive thorough onboarding are more likely to stay with a company long term. Investing in this process early on often leads to higher employee satisfaction and reduced turnover costs."}'::jsonb, '{"exact": "Onboarding new employees effectively can have a lasting impact on how quickly they become productive members of a team. A well-structured onboarding program typically includes clear information about company policies, introductions to key colleagues, and a defined set of goals for the first few months. Many organizations now extend onboarding beyond the first week, recognizing that new employees often need ongoing support as they adjust to new systems and expectations. Assigning a mentor or buddy can help new hires feel more comfortable asking questions without hesitation. Research suggests that employees who receive thorough onboarding are more likely to stay with a company long term. Investing in this process early on often leads to higher employee satisfaction and reduced turnover costs."}'::jsonb, 125, 0.52, 'B2', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000011', 1);
