INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Leila interviewed a promising candidate for the marketing role. She asked thoughtful questions about his previous experience. Impressed by his answers, she recommended him to the hiring manager immediately. He was offered the position the following week."}'::jsonb, '{"key_points": ["Leila interviewed a promising candidate", "she asked about his experience", "she recommended him immediately", "he was offered the position the next week"]}'::jsonb, 37, 0.52, 'B1', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000014', 1),
('passage_reconstruction', '{"passage": "Marcus joined a new company as a graphic designer. During his first week, a mentor patiently explained the team''s workflow. Marcus asked questions whenever something was unclear. By the end of the month, he felt confident working independently."}'::jsonb, '{"key_points": ["Marcus joined as a graphic designer", "a mentor explained the workflow", "he asked questions when unclear", "he felt confident by the end of the month"]}'::jsonb, 37, 0.54, 'B2', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000014', 2),
('passage_reconstruction', '{"passage": "Thank you for applying to the marketing coordinator position. We were impressed by your application and would like to invite you for an interview next week. Please let us know your availability at your earliest convenience."}'::jsonb, '{"key_points": ["thanks for applying", "impressed by the application", "invites for an interview next week", "asks for availability"]}'::jsonb, 35, 0.52, 'B1', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000014', 3),
('passage_reconstruction', '{"passage": "I am pleased to confirm that we would like to offer you the position we discussed. Please review the attached offer letter and let us know if you have any questions before accepting."}'::jsonb, '{"key_points": ["confirms the job offer", "asks them to review the offer letter", "invites questions before accepting"]}'::jsonb, 32, 0.50, 'B1', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000014', 4);
INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "You work in HR. Your manager, Mr. Keller, wants to improve the onboarding experience for new employees. Write an email to him suggesting three ways to achieve this. Your suggestions must come from the following three themes: mentor programs, structured first-week schedules, regular check-in meetings. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.55, 'B2', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000015', 1),
('email_writing', '{"prompt": "You work in recruitment. A candidate, Ms. Haddad, was told the wrong start date for her new position due to an internal mistake. Write an email to her apologizing and correcting the information. Your response must address the following three themes: an apology for the confusion, the correct start date, reassurance about her new role. You should include all three themes with a clear, professional tone."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'c5000000-0000-4000-8000-000000000015', 2);
